"""Game engine: state tracking, conditional checks, and branching playback."""
OPS = {
    "eq": lambda a, b: a == b,
    "ne": lambda a, b: a != b,
    "gt": lambda a, b: a > b,
    "gte": lambda a, b: a >= b,
    "lt": lambda a, b: a < b,
    "lte": lambda a, b: a <= b,
}


class GameEngine:
    def __init__(self, story):
        self.story = story
        self.vars = {}      # relationship/numeric variables
        self.items = set()  # inventory
        self.flags = set()  # boolean story flags
        self.visited = []

    # --- conditional checks -------------------------------------------------
    def check(self, cond):
        if not cond:
            return True
        if "item" in cond:
            return cond["item"] in self.items
        if "no_item" in cond:
            return cond["no_item"] not in self.items
        if "flag" in cond:
            return cond["flag"] in self.flags
        if "no_flag" in cond:
            return cond["no_flag"] not in self.flags
        if "var" in cond:
            value = self.vars.get(cond["var"], 0)
            return OPS[cond.get("op", "eq")](value, cond.get("value", 0))
        return True

    # --- effects -------------------------------------------------------------
    def apply(self, effects):
        for e in effects or []:
            if "item_add" in e:
                self.items.add(e["item_add"])
            elif "item_remove" in e:
                self.items.discard(e["item_remove"])
            elif "flag_set" in e:
                self.flags.add(e["flag_set"])
            elif "flag_clear" in e:
                self.flags.discard(e["flag_clear"])
            elif "var_add" in e:
                key, delta = e["var_add"]
                self.vars[key] = self.vars.get(key, 0) + delta
            elif "var_set" in e:
                key, val = e["var_set"]
                self.vars[key] = val

    # --- playback --------------------------------------------------------------
    def run(self):
        self._banner(self.story.get("title", "AN INTERACTIVE TALE"), "=")
        node_id = self.story["start"]
        while True:
            node = self.story["nodes"].get(node_id)
            if node is None:
                print("\nThe story fades to black... (missing node: %s)" % node_id)
                return
            if not self.check(node.get("condition")):
                node_id = node.get("fallback")
                if node_id is None:
                    print("\nThe path closes; the tale cannot continue.")
                    return
                continue
            self.visited.append(node_id)
            print("\n" + "-" * 62)
            print(node["text"])
            if node.get("ending"):
                self._ending(node)
                return
            choices = node["choices"]
            for i, c in enumerate(choices, 1):
                mark = "" if self.check(c.get("condition")) else "  [locked]"
                print("  %d. %s%s" % (i, c["text"], mark))
            pick = self._prompt(len(choices))
            if pick is None:
                return
            choice = choices[pick - 1]
            if not self.check(choice.get("condition")):
                print(">> That path is barred to you. Choose another.")
                continue
            self.apply(choice.get("effects"))
            node_id = choice["next"]

    def _prompt(self, n):
        while True:
            raw = input("\n> Choose 1-%d (s=status, q=quit): " % n).strip().lower()
            if raw == "q":
                print("Farewell, traveler.")
                return None
            if raw == "s":
                self._status()
                continue
            if raw.isdigit() and 1 <= int(raw) <= n:
                return int(raw)
            print(">> Enter a number between 1 and %d." % n)

    def _status(self):
        rel = ", ".join("%s=%s" % (k, v) for k, v in sorted(self.vars.items())) or "none"
        print("\n[Relationships: %s]" % rel)
        print("[Items: %s]" % (", ".join(sorted(self.items)) or "none"))
        print("[Flags: %s]" % (", ".join(sorted(self.flags)) or "none"))

    def _ending(self, node):
        self._banner("ENDING: " + node["ending"].replace("_", " ").upper(), "*")
        print(node["text"])
        self._status()
        print("\nScenes visited: %d | Thanks for playing!" % len(self.visited))

    @staticmethod
    def _banner(text, ch):
        print("\n" + ch * 62)
        print(text)
        print(ch * 62)
